import subprocess,os,re,json,datetime
command="(Get-CimInstance Win32_Process -Filter 'ProcessId=13436').CommandLine"
p=subprocess.run(['powershell.exe','-NoProfile','-Command',command],capture_output=True,text=True,timeout=7)
cmd=p.stdout.strip()
out={'at':datetime.datetime.now().isoformat(timespec='seconds'),'purpose':'read_only_whitelisted_Chrome_memory_saver_preferences'}
if p.returncode or '--remote-debugging-port=17410' not in cmd:raise RuntimeError('live_chrome_pid_mismatch')
m=re.search(r'--user-data-dir=(?:"([^"]+)"|([^\s"]+))',cmd)
if not m:out['userDataDirConfigured']=False
else:
 root=m.group(1) or m.group(2)
 out['userDataDirConfigured']=True
 out['profilesChecked']=[]
 for sub in ('Default','Profile 1','Profile 2'):
  path=os.path.join(root,sub,'Preferences')
  if not os.path.isfile(path):continue
  try:
   with open(path,'r',encoding='utf-8-sig') as f:z=json.load(f)
   pt=z.get('performance_tuning',{}) if isinstance(z.get('performance_tuning'),dict) else {}
   mem=pt.get('high_efficiency_mode',{}) if isinstance(pt.get('high_efficiency_mode'),dict) else {}
   discard=pt.get('tab_discarding',{}) if isinstance(pt.get('tab_discarding'),dict) else {}
   exceptions=discard.get('exceptions',[])
   out['profilesChecked'].append({'profile':sub,'memorySaverPrefPresent':'state' in mem,'memorySaverState':mem.get('state') if isinstance(mem.get('state'),int) else None,'timerMinutes':mem.get('time_before_discard_in_minutes') if isinstance(mem.get('time_before_discard_in_minutes'),int) else None,'exceptionRuleCount':len(exceptions) if isinstance(exceptions,list) else None,'chatgptExceptionExists':any('chatgpt.com' in str(x).lower() for x in exceptions) if isinstance(exceptions,list) else None})
  except Exception as e:out['profilesChecked'].append({'profile':sub,'error':type(e).__name__})
print(json.dumps(out,ensure_ascii=True)[:2800])
